const titles={overview:['GLOBAL CRM WORKSPACE','Global CRM 전략','시장, 고객군, 연락 조건을 먼저 정하세요.'],event:['EVENT OPERATIONS','이벤트 실행','초청부터 현장, 후속, 정산까지, 누락되는 고객과 업무를 확인하세요.'],preflight:['EVENT PREFLIGHT','운영 사전 점검','운영 조건과 대응안을 비교하세요.'],brief:['PROJECT OVERVIEW','프로젝트 개요','행사 목적, 대상 고객, 일정과 예산을 먼저 정하세요.'],venues:['LOCATION INTELLIGENCE','지역, 공간 비교','지역의 맥락과 실제 공간의 조건을 함께 확인하세요.'],experience:['EXPERIENCE DESIGN','경험, 초청 기획','초청 전 안내, 현장 체험, 행사 후 연락을 순서대로 정하세요.'],operations:['OPERATIONS LAB','운영, 예산 검토','가정을 바꿔 보며 대기, 인력, 비용의 균형을 확인하세요.'],report:['FINAL PORTFOLIO','프로젝트 기획안','제가 조사한 자료, 세운 가정, 계산 기준을 한곳에서 확인할 수 있습니다.']};
const navShort={overview:'CRM 전략',event:'이벤트 실행',preflight:'사전 점검',brief:'프로젝트',venues:'지역 비교',experience:'경험, 초청',operations:'운영, 예산',report:'포트폴리오'};
p=upgrade(p);
